`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (nidepack__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg [31:0] flit;
  wire rd_clk = tb_clk;
  wire wr_clk = tb_clk;
  reg rd_en;
  reg reset;
  wire [31:0] data_out; wire [31:0] ref_data_out;
  reg dq_hi [0:65535]; reg dq_lo [0:65535]; reg [31:0] dq_old; reg [15:0] dq_low; reg [1:0] dq_s; reg dq_re, dq_rst; integer dq_i;
  nidepack dut (.flit(flit), .rd_clk(rd_clk), .wr_clk(wr_clk), .rd_en(rd_en), .reset(reset), .data_out(data_out));
  nidepack__ref ref_i (.flit(flit), .rd_clk(rd_clk), .wr_clk(wr_clk), .rd_en(rd_en), .reset(reset), .data_out(ref_data_out));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1)
      if (ref_data_out[tb_b] !== 1'bx && ref_data_out[tb_b] !== 1'bz && data_out[tb_b] !== ref_data_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 32;
        if (tb_mis <= 15) $display("MISMATCH (secondary, not part of the verdict) t=%0t cycle %0d: data_out = %h, expected %h", $time, tb_cyc, data_out, ref_data_out);
      end
  end endtask
  task tb_props; begin
    if (tb_ph == 0) begin
      if (reset) dq_s = 0;
      else case (dq_s)
        0: if (flit[30:29] == 2'b01) dq_s = 1;
        1: if (flit[30:29] == 2'b00) begin dq_low = flit[15:0]; dq_s = 2; end
        2: if (flit[30:29] == 2'b10) dq_s = 0; else begin dq_hi[flit[15:0]] = 1'b1; dq_lo[dq_low] = 1'b1; dq_s = 1; end
      endcase
    end
    if (tb_ph == 0) begin dq_old = data_out; dq_re = rd_en; dq_rst = reset; end
    else if (tb_started) begin
      if (dq_rst) begin if (data_out !== 32'h60000000) tb_prop("data_out not reset"); end
      else if (data_out !== dq_old) begin
        if (!dq_re) tb_prop("data_out changed without rd_en");
        if (^data_out !== 1'bx && data_out !== 32'h60000000 && !(dq_hi[data_out[31:16]] && dq_lo[data_out[15:0]])) tb_prop("data_out not a word depack assembled from the flits");
      end
    end
  end endtask
  reg [31:0] tbc_p_data_out, tbc_t_data_out;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_data_out = tbc_t_data_out | ((ref_data_out ^ tbc_p_data_out) & ~(ref_data_out ^ ref_data_out)); tbc_p_data_out = ref_data_out;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_data_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1) if (tbc_t_data_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 1 checked outputs toggled, %0d of 32 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    flit = 0; rd_en = 0; reset = 0; reset = 1;
    tbc_t_data_out = 0; tbc_p_data_out = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      flit = {tb_rand(0)};
      if (tb_rand(0) % 3 == 0) rd_en = ~rd_en;
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 400 == 0);
      if (tb_cyc == 0) begin for (dq_i = 0; dq_i < 65536; dq_i = dq_i + 1) begin dq_hi[dq_i] = 1'b0; dq_lo[dq_i] = 1'b0; end dq_s = 0; end
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    $display("INFO cycle-exact mismatches against golden/reference: %0d (secondary)", tb_mis);
    if (tb_perr == 0) $display("ALL TESTS PASSED"); else $display("FAIL: %0d property errors", tb_perr);
    $finish;
  end
endmodule

